{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "@x1aoye/tao-tie-oc",
  "version": "0.0.1",
  "type": "module",
  "private": false,
  "description": "饕餮 (TaoTie) — Context pruning plugin for opencode. Reduces token usage by trimming stale tool outputs automatically.",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js",
      "default": "./dist/index.js"
    }
  },
  "scripts": {
    "clean": "rm -rf dist",
    "build": "npm run clean && tsc",
    "typecheck": "tsc --noEmit",
    "prepublishOnly": "npm run build",
    "dev": "opencode plugin dev"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "plugin",
    "context",
    "pruning",
    "token"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/zoex1aoye/tao-tie-oc.git"
  },
  "bugs": {
    "url": "https://github.com/zoex1aoye/tao-tie-oc/issues"
  },
  "homepage": "https://github.com/zoex1aoye/tao-tie-oc#readme",
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org"
  },
  "engines": {
    "node": ">=18.0.0"
  },
  "author": "zoex",
  "license": "MIT",
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.15.5"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.15.5",
    "@types/node": "^22.0.0",
    "typescript": "^5.7.0"
  },
  "files": [
    "dist/",
    "README.md",
    "LICENSE"
  ]
}

import { loadConfig, resolveConfig } from "./config.js";
import { createEventHandler } from "./session.js";
import { createMessagesTransformHandler } from "./auto-prune.js";
import { createSystemTransformHandler, createCompactingHookHandler } from "./system.js";
const stateMap = new Map();
export default async function plugin(input, _options) {
    const { directory } = input;
    const rawConfig = loadConfig(directory);
    const config = resolveConfig(rawConfig, 1_000_000);
    const debug = config.debug;
    if (debug) {
        // eslint-disable-next-line no-console
        console.log("[tune-context] plugin initialized");
    }
    return {
        event: createEventHandler(stateMap, debug),
        "experimental.chat.messages.transform": createMessagesTransformHandler(stateMap, config, debug),
        "experimental.chat.system.transform": createSystemTransformHandler(stateMap, config),
        "experimental.session.compacting": createCompactingHookHandler(stateMap, config),
    };
}
